1	/**
2	 * NextTermTerminal — experimental terminal backed by the vendored `next-term`
3	 * library (`@/vendor/next-term`) instead of our own AnsiParser/TerminalBuffer.
4	 *
5	 * The vendored lib gives us the VT engine (`BufferSet` + `VTParser`) and a
6	 * `SkiaRenderer` that turns the cell grid into a flat `RenderCommand[]`
7	 * (rect/text/line). It does NOT paint — this component is the Skia surface that
8	 * consumes those commands, plus a hidden TextInput for keyboard input.
9	 *
10	 * Exposes the subset of the terminal handle the screen actually uses
11	 * (`write`/`focus`/`blur`) so it can drop in next to <SkiaTerminal/>.
12	 *
13	 * Scope (experiment): no scrollback gestures or selection yet — keyboard I/O,
14	 * rendering, resize, and DA/DSR responses. Per-cell text commands (the lib
15	 * doesn't batch runs) make this heavier than our own renderer; fine for A/B.
16	 */
17	
18	import React, {
19	  forwardRef,
20	  useCallback,
21	  useEffect,
22	  useImperativeHandle,
23	  useMemo,
24	  useRef,
25	  useState,
26	} from 'react';
27	import {
28	  View,
29	  TextInput,
30	  Pressable,
31	  Keyboard,
32	  Dimensions,
33	  StyleSheet,
34	  Platform,
35	  NativeSyntheticEvent,
36	  TextInputKeyPressEventData,
37	  LayoutChangeEvent,
38	} from 'react-native';
39	import {
40	  Canvas,
41	  Fill,
42	  Rect,
43	  Text as SkiaText,
44	  matchFont,
45	} from '@shopify/react-native-skia';
46	import type { SkFont } from '@shopify/react-native-skia';
47	import {
48	  BufferSet,
49	  VTParser,
50	  DEFAULT_THEME as CORE_DEFAULT_THEME,
51	} from '@/vendor/next-term/core';
52	import type { Buffer, Theme as CoreTheme } from '@/vendor/next-term/core';
53	import { SkiaRenderer } from '@/vendor/next-term/SkiaRenderer';
54	import type { RenderCommand } from '@/vendor/next-term/SkiaRenderer';
55	import type { TerminalTheme } from './SkiaTerminalRenderer';
56	
57	// ────────────────────────────────────────────────────────────────────────────
58	// Types
59	// ────────────────────────────────────────────────────────────────────────────
60	
61	export interface NextTermTerminalHandle {
62	  write: (data: string) => void;
63	  focus: () => void;
64	  blur: () => void;
65	}
66	
67	export interface NextTermTerminalProps {
68	  fontSize?: number;
69	  /** App-shaped theme (ansiColors[0..15] + named); mapped to the core Theme. */
70	  theme?: TerminalTheme;
71	  scrollback?: number;
72	  onData?: (data: string) => void;
73	  onResize?: (cols: number, rows: number) => void;
74	  onTitleChange?: (title: string) => void;
75	  /** Accepted for prop-compatibility with <SkiaTerminal/>; unused here. */
76	  cursorBlinkInterval?: number;
77	}
78	
79	// ────────────────────────────────────────────────────────────────────────────
80	// Helpers
81	// ────────────────────────────────────────────────────────────────────────────
82	
83	/** Map our app theme (ansiColors[16]) onto the vendored core Theme. */
84	function toCoreTheme(t?: TerminalTheme): CoreTheme {
85	  if (!t) return CORE_DEFAULT_THEME;
86	  const a = t.ansiColors ?? [];
87	  const at = (i: number, fallback: string) => a[i] ?? fallback;
88	  return {
89	    foreground: t.foreground,
90	    background: t.background,
91	    cursor: t.cursor,
92	    cursorAccent: t.cursorAccent,
93	    selectionBackground: t.selectionBackground,
94	    black: at(0, CORE_DEFAULT_THEME.black),
95	    red: at(1, CORE_DEFAULT_THEME.red),
96	    green: at(2, CORE_DEFAULT_THEME.green),
97	    yellow: at(3, CORE_DEFAULT_THEME.yellow),
98	    blue: at(4, CORE_DEFAULT_THEME.blue),
99	    magenta: at(5, CORE_DEFAULT_THEME.magenta),
100	    cyan: at(6, CORE_DEFAULT_THEME.cyan),
101	    white: at(7, CORE_DEFAULT_THEME.white),
102	    brightBlack: at(8, CORE_DEFAULT_THEME.brightBlack),
103	    brightRed: at(9, CORE_DEFAULT_THEME.brightRed),
104	    brightGreen: at(10, CORE_DEFAULT_THEME.brightGreen),
105	    brightYellow: at(11, CORE_DEFAULT_THEME.brightYellow),
106	    brightBlue: at(12, CORE_DEFAULT_THEME.brightBlue),
107	    brightMagenta: at(13, CORE_DEFAULT_THEME.brightMagenta),
108	    brightCyan: at(14, CORE_DEFAULT_THEME.brightCyan),
109	    brightWhite: at(15, CORE_DEFAULT_THEME.brightWhite),
110	  };
111	}
112	
113	// Skia throws on a color it can't parse; the renderer emits hex + rgb(), but
114	// guard anyway so a stray value can't crash the native surface.
115	const VALID_COLOR_RE = /^(#[0-9a-fA-F]{3,8}|rgba?\([^)]*\)|transparent)$/;
116	function safeColor(c: string | undefined, fallback: string): string {
117	  return typeof c === 'string' && VALID_COLOR_RE.test(c) ? c : fallback;
118	}
119	
120	const sharedEncoder = typeof TextEncoder !== 'undefined' ? new TextEncoder() : null;
121	function encodeUtf8(s: string): Uint8Array {
122	  if (sharedEncoder) return sharedEncoder.encode(s);
123	  const out = new Uint8Array(s.length);
124	  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i) & 0xff;
125	  return out;
126	}
127	/** Parser responses (DA/DSR/etc.) are ASCII escape sequences. */
128	function decodeAscii(bytes: Uint8Array): string {
129	  let s = '';
130	  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
131	  return s;
132	}
133	
134	function matchMono(
135	  fontSize: number,
136	  fontWeight: 'normal' | 'bold',
137	  fontStyle: 'normal' | 'italic',
138	): SkFont | null {
139	  try {
140	    return matchFont({ fontFamily: 'monospace', fontSize, fontWeight, fontStyle });
141	  } catch {
142	    return null;
143	  }
144	}
145	
146	function useMonoFonts(fontSize: number) {
147	  const regular = useMemo(() => matchMono(fontSize, 'normal', 'normal'), [fontSize]);
148	  const bold = useMemo(() => matchMono(fontSize, 'bold', 'normal'), [fontSize]);
149	  const italic = useMemo(() => matchMono(fontSize, 'normal', 'italic'), [fontSize]);
150	  const boldItalic = useMemo(() => matchMono(fontSize, 'bold', 'italic'), [fontSize]);
151	  return { regular, bold, italic, boldItalic };
152	}
153	
154	function clamp(n: number, min: number, max: number): number {
155	  return Math.max(min, Math.min(max, n));
156	}
157	
158	function copyBufferRows(source: Buffer, target: Buffer): void {
159	  const rowsToCopy = Math.min(source.rows, target.rows);
160	  const maxSourceStart = source.rows - rowsToCopy;
161	  const sourceStart = source.cursor.row < target.rows
162	    ? 0
163	    : clamp(source.cursor.row - target.rows + 1, 0, maxSourceStart);
164	  const targetStart = 0;
165	
166	  for (let i = 0; i < rowsToCopy; i++) {
167	    const sourceRow = sourceStart + i;
168	    const targetRow = targetStart + i;
169	    target.grid.pasteRow(
170	      targetRow,
171	      source.grid.copyRow(sourceRow),
172	      source.grid.isWrapped(sourceRow),
173	    );
174	  }
175	
176	  const rowDelta = targetStart - sourceStart;
177	  target.cursor = {
178	    ...source.cursor,
179	    row: clamp(source.cursor.row + rowDelta, 0, target.rows - 1),
180	    col: clamp(source.cursor.col, 0, target.cols - 1),
181	  };
182	  if (source.scrollTop === 0 && source.scrollBottom === source.rows - 1) {
183	    target.scrollTop = 0;
184	    target.scrollBottom = target.rows - 1;
185	  } else {
186	    target.scrollTop = clamp(source.scrollTop + rowDelta, 0, target.rows - 1);
187	    target.scrollBottom = clamp(source.scrollBottom + rowDelta, target.scrollTop, target.rows - 1);
188	  }
189	  for (const col of source.tabStops) {
190	    if (col >= 0 && col < target.cols) target.tabStops.add(col);
191	  }
192	  target.grid.markAllDirty();
193	}
194	
195	function copyScrollback(source: BufferSet, target: BufferSet): void {
196	  const start = Math.max(0, source.scrollback.length - target.maxScrollback);
197	  target.scrollback = source.scrollback.slice(start);
198	  target.scrollbackWrap = source.scrollbackWrap.slice(start);
199	  target.scrollbackCompact = source.scrollbackCompact.slice(start);
200	}
201	
202	function resizeBufferSet(source: BufferSet, cols: number, rows: number, scrollback: number): BufferSet {
203	  const target = new BufferSet(cols, rows, scrollback);
204	  copyBufferRows(source.normal, target.normal);
205	  copyBufferRows(source.alternate, target.alternate);
206	  copyScrollback(source, target);
207	  target.setActive(source.isAlternate);
208	  return target;
209	}
210	
211	// ────────────────────────────────────────────────────────────────────────────
212	// Component
213	// ────────────────────────────────────────────────────────────────────────────
214	
215	export const NextTermTerminal = forwardRef<NextTermTerminalHandle, NextTermTerminalProps>(
216	  function NextTermTerminal(
217	    { fontSize = 13, theme, scrollback = 1000, onData, onResize, onTitleChange },
218	    ref,
219	  ) {
220	    // ── Layout / keyboard avoidance ───────────────────────────────────
221	    const [layout, setLayout] = useState({ width: 0, height: 0 });
222	    const [keyboardHeight, setKeyboardHeight] = useState(0);
223	    const screen = Dimensions.get('window');
224	    const containerWidth = layout.width || screen.width;
225	    const containerHeight = (layout.height || screen.height) - keyboardHeight;
226	
227	    const coreTheme = useMemo(() => toCoreTheme(theme), [theme]);
228	    const fonts = useMonoFonts(fontSize);
229	
230	    // ── Renderer (geometry source of truth) ───────────────────────────
231	    const rendererRef = useRef<SkiaRenderer | null>(null);
232	    if (!rendererRef.current) {
233	      rendererRef.current = new SkiaRenderer({ fontSize, fontFamily: 'monospace', theme: coreTheme });
234	    }
235	    const { width: cellWidth, height: cellHeight } = rendererRef.current.getCellSize();
236	    const cols = Math.max(2, Math.floor(containerWidth / cellWidth));
237	    const rows = Math.max(1, Math.floor(containerHeight / cellHeight));
238	
239	    // ── VT engine ─────────────────────────────────────────────────────
240	    const bufferSetRef = useRef<BufferSet | null>(null);
241	    const parserRef = useRef<VTParser | null>(null);
242	    if (!bufferSetRef.current) {
243	      bufferSetRef.current = new BufferSet(cols, rows, scrollback);
244	      parserRef.current = new VTParser(bufferSetRef.current);
245	    }
246	
247	    const [commands, setCommands] = useState<RenderCommand[]>([]);
248	    const textInputRef = useRef<TextInput>(null);
249	
250	    const onDataRef = useRef(onData);
251	    useEffect(() => { onDataRef.current = onData; }, [onData]);
252	
253	    // ── Render (rAF-debounced full-grid pass) ─────────────────────────
254	    const rafRef = useRef<number | null>(null);
255	    const pendingRender = useRef(false);
256	    const renderNow = useCallback(() => {
257	      const bs = bufferSetRef.current;
258	      const rd = rendererRef.current;
259	      if (!bs || !rd) return;
260	      try {
261	        const cmds = rd.renderFrame(bs.active.grid, bs.active.cursor, null);
262	        setCommands(cmds);
263	        const grid = bs.active.grid;
264	        for (let r = 0; r < grid.rows; r++) grid.clearDirty(r);
265	      } catch {
266	        // Keep the session alive on a transient render glitch.
267	      }
268	    }, []);
269	    const scheduleRender = useCallback(() => {
270	      if (pendingRender.current) return;
271	      pendingRender.current = true;
272	      rafRef.current = requestAnimationFrame(() => {
273	        pendingRender.current = false;
274	        renderNow();
275	      });
276	    }, [renderNow]);
277	    useEffect(() => () => { if (rafRef.current != null) cancelAnimationFrame(rafRef.current); }, []);
278	
279	    // Drain DA/DSR/etc. replies the parser queued, back to the PTY.
280	    const drainResponses = useCallback(() => {
281	      const parser = parserRef.current;
282	      if (!parser) return;
283	      while (parser.hasResponse()) {
284	        const r = parser.readResponse();
285	        if (!r) break;
286	        onDataRef.current?.(decodeAscii(r));
287	      }
288	    }, []);
289	
290	    // Title callback
291	    useEffect(() => {
292	      if (onTitleChange) parserRef.current?.setTitleChangeCallback(onTitleChange);
293	    }, [onTitleChange]);
294	
295	    // Theme / font updates
296	    useEffect(() => { rendererRef.current?.setTheme(coreTheme); scheduleRender(); }, [coreTheme, scheduleRender]);
297	    useEffect(() => { rendererRef.current?.setFont(fontSize, 'monospace'); scheduleRender(); }, [fontSize, scheduleRender]);
298	
299	    // ── Resize: the lib has no in-place resize, so rebuild while preserving
300	    // the visible grid. Focusing the hidden input changes keyboard height,
301	    // which otherwise created a fresh blank terminal.
302	    const sizeRef = useRef({ cols, rows });
303	    useEffect(() => {
304	      if (cols === sizeRef.current.cols && rows === sizeRef.current.rows) return;
305	      sizeRef.current = { cols, rows };
306	      const previous = bufferSetRef.current;
307	      const bs = previous
308	        ? resizeBufferSet(previous, cols, rows, scrollback)
309	        : new BufferSet(cols, rows, scrollback);
310	      bufferSetRef.current = bs;
311	      const parser = new VTParser(bs);
312	      if (onTitleChange) parser.setTitleChangeCallback(onTitleChange);
313	      parserRef.current = parser;
314	      onResize?.(cols, rows);
315	      scheduleRender();
316	    }, [cols, rows, scrollback, onResize, onTitleChange, scheduleRender]);
317	
318	    // ── Keyboard avoidance ────────────────────────────────────────────
319	    useEffect(() => {
320	      const show = Keyboard.addListener(
321	        Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow',
322	        (e) => setKeyboardHeight(e.endCoordinates.height),
323	      );
324	      const hide = Keyboard.addListener(
325	        Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide',
326	        () => setKeyboardHeight(0),
327	      );
328	      return () => { show.remove(); hide.remove(); };
329	    }, []);
330	
331	    // ── Imperative handle ─────────────────────────────────────────────
332	    useImperativeHandle(ref, () => ({
333	      write: (data: string) => {
334	        const parser = parserRef.current;
335	        if (!parser) return;
336	        try { parser.write(encodeUtf8(data)); } catch {}
337	        drainResponses();
338	        scheduleRender();
339	      },
340	      focus: () => textInputRef.current?.focus(),
341	      blur: () => textInputRef.current?.blur(),
342	    }), [drainResponses, scheduleRender]);
343	
344	    // ── Keyboard input ────────────────────────────────────────────────
345	    const sendData = useCallback((data: string) => { onDataRef.current?.(data); }, []);
346	    const lastInputRef = useRef('');
347	    const handleKeyPress = useCallback((e: NativeSyntheticEvent<TextInputKeyPressEventData>) => {
348	      const { key } = e.nativeEvent;
349	      const map: Record<string, string> = {
350	        Enter: '\r', Backspace: '\x7f', Escape: '\x1b', Tab: '\t',
351	        ArrowUp: '\x1b[A', ArrowDown: '\x1b[B', ArrowRight: '\x1b[C', ArrowLeft: '\x1b[D',
352	      };
353	      if (map[key]) { sendData(map[key]); lastInputRef.current = key; }
354	      else if (key.length === 1) { sendData(key); lastInputRef.current = key; }
355	    }, [sendData]);
356	    const handleChangeText = useCallback((text: string) => {
357	      if (text.length > 0 && text !== lastInputRef.current) sendData(text);
358	      lastInputRef.current = '';
359	      setTimeout(() => textInputRef.current?.clear(), 0);
360	    }, [sendData]);
361	
362	    const onLayout = useCallback((e: LayoutChangeEvent) => {
363	      const { width, height } = e.nativeEvent.layout;
364	      setLayout({ width, height });
365	    }, []);
366	
367	    // ── Paint ─────────────────────────────────────────────────────────
368	    const selectFont = (bold?: boolean, italic?: boolean): SkFont | null => {
369	      if (bold && italic) return fonts.boldItalic ?? fonts.regular;
370	      if (bold) return fonts.bold ?? fonts.regular;
371	      if (italic) return fonts.italic ?? fonts.regular;
372	      return fonts.regular;
373	    };
374	
375	    const safeW = Number.isFinite(containerWidth) && containerWidth > 0 ? containerWidth : 1;
376	    const safeH = Number.isFinite(containerHeight) && containerHeight > 0 ? containerHeight : 1;
377	    const bg = safeColor(coreTheme.background, '#1e1e1e');
378	
379	    return (
380	      <View style={styles.fill} onLayout={onLayout}>
381	        <Pressable style={styles.fill} onPress={() => textInputRef.current?.focus()}>
382	          <Canvas style={{ width: safeW, height: safeH }}>
383	            <Fill color={bg} />
384	            {commands.map((cmd, i) => {
385	              if (cmd.type === 'text') {
386	                if (!cmd.text) return null;
387	                const font = selectFont(cmd.bold, cmd.italic);
388	                if (!font) return null;
389	                return (
390	                  <SkiaText
391	                    key={i}
392	                    x={cmd.x}
393	                    y={cmd.y}
394	                    text={cmd.text}
395	                    font={font}
396	                    color={safeColor(cmd.color, coreTheme.foreground)}
397	                    opacity={cmd.opacity ?? 1}
398	                  />
399	                );
400	              }
401	              // rect + line (line is just a 1px-tall rect with the given width)
402	              return (
403	                <Rect
404	                  key={i}
405	                  x={cmd.x}
406	                  y={cmd.y}
407	                  width={cmd.width ?? 0}
408	                  height={cmd.height ?? (cmd.type === 'line' ? 1 : 0)}
409	                  color={safeColor(cmd.color, bg)}
410	                  opacity={cmd.opacity ?? 1}
411	                />
412	              );
413	            })}
414	          </Canvas>
415	        </Pressable>
416	
417	        <TextInput
418	          ref={textInputRef}
419	          style={styles.hiddenInput}
420	          autoCapitalize="none"
421	          autoCorrect={false}
422	          autoComplete="off"
423	          spellCheck={false}
424	          keyboardType="ascii-capable"
425	          keyboardAppearance="dark"
426	          onKeyPress={handleKeyPress}
427	          onChangeText={handleChangeText}
428	          blurOnSubmit={false}
429	          caretHidden
430	          textContentType="none"
431	          importantForAutofill="no"
432	        />
433	      </View>
434	    );
435	  },
436	);
437	
438	NextTermTerminal.displayName = 'NextTermTerminal';
439	
440	const styles = StyleSheet.create({
441	  fill: { flex: 1 },
442	  hiddenInput: {
443	    position: 'absolute',
444	    opacity: 0,
445	    width: 1,
446	    height: 1,
447	    left: -9999,
448	    top: -9999,
449	  },
450	});
