121	
122	  const [spriteName, setSpriteName] = useState(paramName);
123	  const [cwd, setCwd] = useState(paramCwd);
124	  const [resumeSessionId, setResumeSessionId] = useState(paramResumeSessionId);
125	  // With a working directory we launch a shell and type `cd <dir> && <command>`,
126	  // which works no matter how the exec endpoint tokenizes `cmd`.
127	  const [command, setCommand] = useState(routeCommand);
128	  const [attachSessionId, setAttachSessionId] = useState(paramAttachSessionId);
129	  const [sessionId, setSessionId] = useState<string | undefined>();
130	  const [state, setState] = useState<ExecConnectionState>('idle');
131	  const [showSetup, setShowSetup] = useState(!paramName);
132	  // Bumped to force a clean remount of the terminal (fresh buffer) after the
133	  // error boundary catches, without tearing down the live WebSocket session.
134	  const [terminalEpoch, setTerminalEpoch] = useState(0);
135	
136	  const termRef = useRef<SkiaTerminalHandle>(null);
137	  const nextTermRef = useRef<NextTermTerminalHandle>(null);
138	  const didAutoConnectRef = useRef(false);
139	
140	  // Which terminal renderer is mounted. `engineRef` mirrors it for callbacks
141	  // (appendLog, focus) that are created once and must read the latest value.
142	  const [engine, setEngine] = useState<TerminalEngine>(initialEngine);
143	  const engineRef = useRef<TerminalEngine>(engine);
144	  useEffect(() => { engineRef.current = engine; }, [engine]);
145	
146	  const writeToActiveTerminal = useCallback((data: string) => {
147	    if (engineRef.current === 'next-term') nextTermRef.current?.write(data);
148	    else termRef.current?.write(data);
149	  }, []);
150	
151	  const focusActiveTerminal = useCallback(() => {
152	    if (engineRef.current === 'next-term') nextTermRef.current?.focus();
153	    else termRef.current?.focus();
154	  }, []);
155	
156	  const appendLog = useCallback((entry: ExecEventLog) => {
157	    // Defense in depth: termRef.write → buffer.write already contains parser throws,
158	    // but keep this path total too so a logging write can never bubble up here.
159	    try {
160	      if (entry.source === 'ws') {
161	        writeToActiveTerminal(entry.text);
162	      } else if (entry.source === 'error') {
163	        writeToActiveTerminal(`\r\n\x1b[31m[ERROR]\x1b[0m ${entry.text}\r\n`);
164	      }
165	    } catch (e) {
166	      terror('screen.appendLog', 'write threw', { err: errInfo(e), source: entry.source });
167	    }
168	  }, [writeToActiveTerminal]);
169	
170	  const client = useMemo(
171	    () =>
172	      createExecPocClient({
173	        onStateChange: setState,
174	        onSessionId: setSessionId,
175	        onLog: appendLog,
176	      }),
177	    [appendLog]
178	  );
179	
180	  useEffect(() => () => client.close(), [client]);
181	
182	  // Auto-connect on mount. Route params can target a sprite, cwd, command, or existing session.
183	  useEffect(() => {
184	    if (didAutoConnectRef.current || !paramName) return;
185	    didAutoConnectRef.current = true;
186	
187	    const startupCommand = paramResumeSessionId ? buildResumeCommand(paramResumeSessionId) : routeCommand;
188	    const initialInput = paramAttachSessionId ? undefined : buildInitialInput(paramCwd, startupCommand);
189	
190	    (async () => {
191	      try {
192	        await client.connect({
193	          spriteName: paramName,
194	          command: DEFAULT_SHELL_COMMAND,
195	          attachSessionId: paramAttachSessionId || undefined,
196	          initialInput,
197	        });
198	        setShowSetup(false);
199	        focusActiveTerminal();
200	      } catch (error) {
201	        appendLog({
202	          timestamp: Date.now(),
203	          source: 'error',
204	          text: `Connect failed: ${(error as Error).message}`,
205	        });
206	      }
207	    })();
208	  }, [
209	    paramName,
210	    paramCwd,
211	    paramCmd,
212	    paramAttachSessionId,
213	    paramResumeSessionId,
214	    routeCommand,
215	    client,
216	    appendLog,
217	  ]);
218	
219	  const connect = async () => {
220	    if (!spriteName.trim()) {
221	      Alert.alert('Missing sprite name', 'Enter a sprite name first.');
222	      return;
223	    }
224	    try {
225	      const nextResumeSessionId = resumeSessionId.trim();
226	      const startupCommand = nextResumeSessionId
227	        ? buildResumeCommand(nextResumeSessionId)
228	        : command.trim();
229	      const nextAttachSessionId = attachSessionId.trim() || undefined;
230	      const initialInput = nextAttachSessionId ? undefined : buildInitialInput(cwd, startupCommand);
231	      await client.connect({
232	        spriteName: spriteName.trim(),
233	        command: DEFAULT_SHELL_COMMAND,
234	        attachSessionId: nextAttachSessionId,
235	        initialInput,
236	      });
237	      setShowSetup(false);
238	      focusActiveTerminal();
239	    } catch (error) {
240	      appendLog({ timestamp: Date.now(), source: 'error', text: `Connect failed: ${(error as Error).message}` });
241	    }
242	  };
243	
244	  const disconnect = () => {
245	    client.close();
246	    setState('closed');
247	  };
248	
249	  // Re-mount the terminal with a clean buffer after a render error, then nudge
250	  // the remote app to repaint into the fresh screen.
251	  const handleTerminalReset = useCallback(() => {
252	    tinfo('screen.reset', 'terminal error boundary reset — remounting with fresh buffer');
253	    setTerminalEpoch((e) => e + 1);
254	    setTimeout(() => {
255	      focusActiveTerminal();
256	      if (client.getState() === 'open') client.send('\f', false);
257	    }, 50);
258	  }, [client, focusActiveTerminal]);
259	
260	  // Swap terminal engines. The freshly-mounted engine starts with a blank
261	  // buffer, so nudge a repaint (Ctrl-L) once it's attached.
262	  const toggleEngine = useCallback(() => {
263	    setEngine((prev) => (prev === 'builtin' ? 'next-term' : 'builtin'));
264	    setTimeout(() => {
265	      focusActiveTerminal();
266	      if (client.getState() === 'open') client.send('\f', false);
267	    }, 60);
268	  }, [client, focusActiveTerminal]);
269	
270	  const copyLogs = useCallback(async () => {
271	    const dump = dumpTerminalLog();
272	    try {
273	      await Clipboard.setStringAsync(dump);
274	      Alert.alert('Terminal logs copied', `${dump.split('\n').length} lines copied to clipboard. Paste them to share.`);
275	    } catch (e) {
276	      Alert.alert('Copy failed', (e as Error).message);
277	    }
278	  }, []);
279	
280	  const isConnected = state === 'open';
281	
282	  return (
283	    <SafeAreaView style={[styles.container, { backgroundColor: '#010409' }]} edges={['top']}>
284	      {/* No KeyboardAvoidingView here: SkiaTerminal owns keyboard avoidance, and
285	          stacking both double-subtracts the keyboard height (jumpy canvas + a
286	          flood of resize events to the PTY). */}
287	      <View style={styles.container}>
288	        {/* Header */}
289	        <View style={styles.header}>
290	          <Pressable onPress={() => router.back()} hitSlop={8}>
291	            <Text style={styles.headerLink}>Back</Text>
292	          </Pressable>
293	          <View style={styles.headerCenter}>
294	            <View style={[styles.statusDot, { backgroundColor: STATE_COLORS[state] }]} />
295	            <Text style={styles.headerTitle}>
296	              {sessionId ? `Session ${sessionId}` : 'Terminal'}
297	            </Text>
298	          </View>
299	          <View style={styles.headerActions}>
300	            {Platform.OS !== 'web' && (
301	              <Pressable onPress={toggleEngine} hitSlop={8}>
302	                <Text style={[styles.headerLink, engine === 'next-term' && { color: '#bc8cff' }]}>
303	                  {engine === 'next-term' ? 'next-term' : 'built-in'}
304	                </Text>
305	              </Pressable>
306	            )}
307	            <Pressable onPress={copyLogs} onLongPress={() => { clearTerminalLog(); Alert.alert('Terminal logs cleared'); }} hitSlop={8}>
308	              <Text style={styles.headerLink}>Logs</Text>
309	            </Pressable>
310	            <Pressable onPress={() => setShowSetup((v) => !v)} hitSlop={8}>
311	              <Text style={[styles.headerLink, showSetup && { color: '#58a6ff' }]}>
312	                {showSetup ? 'Hide' : 'Setup'}
313	              </Text>
314	            </Pressable>
315	          </View>
316	        </View>
317	
318	        {/* Setup panel */}
319	        {showSetup && (
320	          <View style={styles.setupPanel}>
321	            <View style={styles.setupRow}>
322	              <TextInput
323	                style={styles.setupInput}
324	                placeholder="sprite-name"
325	                placeholderTextColor="#484f58"
326	                autoCapitalize="none"
327	                autoCorrect={false}
328	                value={spriteName}
329	                onChangeText={setSpriteName}
330	              />
331	              <TextInput
332	                style={[styles.setupInput, { flex: 0.6 }]}
333	                placeholder="command"
334	                placeholderTextColor="#484f58"
335	                autoCapitalize="none"
336	                autoCorrect={false}
337	                value={command}
338	                onChangeText={setCommand}
339	              />
340	            </View>
341	            <View style={styles.setupRow}>
342	              <TextInput
343	                style={styles.setupInput}
344	                placeholder="working directory, e.g. ~/type/type_new"
345	                placeholderTextColor="#484f58"
346	                autoCapitalize="none"
347	                autoCorrect={false}
348	                value={cwd}
349	                onChangeText={setCwd}
350	              />
351	            </View>
352	            <View style={styles.setupRow}>
353	              <TextInput
354	                style={styles.setupInput}
355	                placeholder="claude resume session ID (optional)"
356	                placeholderTextColor="#484f58"
357	                autoCapitalize="none"
358	                autoCorrect={false}
359	                value={resumeSessionId}
360	                onChangeText={setResumeSessionId}
361	              />
362	            </View>
363	            <View style={styles.setupRow}>
364	              <TextInput
365	                style={styles.setupInput}
366	                placeholder="attach session ID (optional)"
367	                placeholderTextColor="#484f58"
368	                autoCapitalize="none"
369	                autoCorrect={false}
370	                value={attachSessionId}
371	                onChangeText={setAttachSessionId}
372	              />
373	              <Pressable
374	                style={({ pressed }) => [
375	                  styles.connectButton,
376	                  isConnected
377	                    ? { backgroundColor: '#21262d', borderColor: '#30363d' }
378	                    : { backgroundColor: '#238636', borderColor: '#2ea043' },
379	                  pressed && { opacity: 0.7 },
380	                ]}
381	                onPress={isConnected ? disconnect : connect}
382	              >
383	                <Text style={[styles.connectButtonText, isConnected && { color: '#f0f6fc' }]}>
384	                  {isConnected ? 'Disconnect' : state === 'connecting' ? 'Connecting...' : 'Connect'}
385	                </Text>
386	              </Pressable>
387	            </View>
388	          </View>
389	        )}
390	
391	        {/* Quick keys */}
392	        {isConnected && (
393	          <ScrollView
394	            horizontal
395	            style={styles.keysScroll}
396	            contentContainerStyle={styles.keysRow}
397	            showsHorizontalScrollIndicator={false}
398	          >
399	            {QUICK_CONTROLS.map((c) => (
400	              <Pressable
401	                key={c.label}
402	                style={({ pressed }) => [styles.keyButton, pressed && { opacity: 0.6 }]}
403	                onPress={() => client.send(c.payload, false)}
404	              >
405	                <Text style={styles.keyLabel}>{c.label}</Text>
406	              </Pressable>
407	            ))}
408	          </ScrollView>
409	        )}
410	
411	        {/* Terminal */}
412	        <View style={styles.terminalContainer}>
413	          <TerminalErrorBoundary key={terminalEpoch} onReset={handleTerminalReset}>
414	            {Platform.OS === 'web' ? (
415	              <WebTerminal
416	                termRef={termRef}
417	                onData={(data) => {
418	                  if (client.getState() === 'open') client.send(data, false);
419	                }}
420	                onResize={(cols, rows) => client.resize(cols, rows)}
421	                theme={TERMINAL_THEME}
422	              />
423	            ) : engine === 'next-term' ? (
424	              <NextTermTerminalNative
425	                ref={nextTermRef}
426	                onData={(data: string) => {
427	                  if (client.getState() === 'open') client.send(data, false);
428	                }}
429	                onResize={(cols: number, rows: number) => client.resize(cols, rows)}
430	                fontSize={13}
431	                theme={TERMINAL_THEME}
432	              />
433	            ) : (
434	              <SkiaTerminalNative
435	                ref={termRef}
436	                onData={(data: string) => {
437	                  if (client.getState() === 'open') client.send(data, false);
438	                }}
439	                onResize={(cols: number, rows: number) => client.resize(cols, rows)}
440	                fontSize={13}
441	                cursorBlinkInterval={600}
442	                theme={TERMINAL_THEME}
443	              />
444	            )}
445	          </TerminalErrorBoundary>
446	        </View>
447	      </View>
448	    </SafeAreaView>
449	  );
450	}
451	
452	const styles = StyleSheet.create({
453	  container: {
454	    flex: 1,
455	  },
456	  // ── Header ──
