    gap: 8,
  },
  setupInput: {
    flex: 1,
    backgroundColor: '#0d1117',
    borderWidth: 1,
    borderColor: '#30363d',
    borderRadius: 6,
    paddingHorizontal: 10,
    paddingVertical: 6,
    color: '#c9d1d9',
    fontSize: 13,
  },
  connectButton: {
    borderWidth: 1,
