1	/**
2	 * SkiaTerminal — complete terminal component
3	 *
4	 * Features:
5	 *   - WebSocket connection with reconnect support
6	 *   - Gesture-based scrollback (pan up/down through history)
7	 *   - Text selection via long-press + drag
8	 *   - Keyboard input with Ctrl/Meta modifier support
9	 *   - requestAnimationFrame-based render debouncing
10	 *   - Bell event callback
11	 *   - Title change callback (OSC 0/2)
12	 *   - Connection status tracking
13	 *   - Keyboard avoidance (adjust height when keyboard shows)
14	 */
15	
16	import React, { useCallback, useEffect, useRef, useState, useMemo } from 'react';
17	import {
18	  View,
19	  Text,
20	  TextInput,
21	  Pressable,
22	  Keyboard,
23	  Dimensions,
24	  StyleSheet,
25	  Platform,
26	  NativeSyntheticEvent,
27	  TextInputKeyPressEventData,
28	  LayoutChangeEvent,
29	  Vibration,
30	} from 'react-native';
31	import {
32	  GestureDetector,
33	  Gesture,
34	  GestureHandlerRootView,
35	} from 'react-native-gesture-handler';
36	import { runOnJS } from 'react-native-reanimated';
37	import * as Clipboard from 'expo-clipboard';
38	import { TerminalBuffer } from './TerminalBuffer';
39	import { tinfo, tdebug, twarn, hexPreview } from './terminalLog';
40	import {
41	  SkiaTerminalRenderer,
42	  TerminalTheme,
43	  DEFAULT_THEME,
44	  SelectionRange,
45	  FontConfig,
46	  CellMetrics,
47	  measureCell,
48	} from './SkiaTerminalRenderer';
49	
50	// ────────────────────────────────────────────────────────────────────────────
51	// Types
52	// ────────────────────────────────────────────────────────────────────────────
53	
54	export type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error';
55	
56	export interface SkiaTerminalProps {
57	  wsUrl?: string;
58	  webSocket?: WebSocket;
59	  cols?: number;
60	  rows?: number;
61	  fontSize?: number;
62	  fontConfig?: FontConfig;
63	  scrollback?: number;
64	  theme?: TerminalTheme;
65	  cursorBlinkInterval?: number;
66	  /** Called when user types (data sent to server) */
67	  onData?: (data: string) => void;
68	  /** Called on OSC title change */
69	  onTitleChange?: (title: string) => void;
70	  /** Called on BEL */
71	  onBell?: () => void;
72	  /** Called when connection status changes */
73	  onConnectionChange?: (status: ConnectionStatus) => void;
74	  /** Called when selection changes */
75	  onSelectionChange?: (text: string | null) => void;
76	  /** Called when terminal resizes */
77	  onResize?: (cols: number, rows: number) => void;
78	  width?: number;
79	  height?: number;
80	}
81	
82	export interface SkiaTerminalHandle {
83	  write: (data: string) => void;
84	  focus: () => void;
85	  blur: () => void;
86	  getSelection: () => string | null;
87	  clearSelection: () => void;
88	  scrollToBottom: () => void;
89	  buffer: TerminalBuffer;
90	}
91	
92	// ────────────────────────────────────────────────────────────────────────────
93	// Selection text extraction
94	// ────────────────────────────────────────────────────────────────────────────
95	
96	function extractSelectionText(
97	  buffer: TerminalBuffer,
98	  selection: SelectionRange,
99	): string {
100	  let [sx, sy] = selection.start;
101	  let [ex, ey] = selection.end;
102	  if (sy > ey || (sy === ey && sx > ex)) {
103	    [sx, sy, ex, ey] = [ex, ey, sx, sy];
104	  }
105	
106	  const lines: string[] = [];
107	  const viewportLines = buffer.getViewportLines();
108	
109	  for (let y = sy; y <= ey; y++) {
110	    const line = viewportLines[y];
111	    if (!line) continue;
112	
113	    const startX = y === sy ? sx : 0;
114	    const endX = y === ey ? ex : line.length;
115	    let row = '';
116	    for (let x = startX; x < endX; x++) {
117	      row += line[x]?.char || ' ';
118	    }
119	    lines.push(row.trimEnd());
120	  }
121	
122	  return lines.join('\n');
123	}
124	
125	async function copyToClipboard(text: string): Promise<void> {
126	  if (Platform.OS === 'web') {
127	    try {
128	      await navigator.clipboard.writeText(text);
129	    } catch {}
130	  } else {
131	    await Clipboard.setStringAsync(text);
132	  }
133	}
134	
135	function findWordAt(
136	  buffer: TerminalBuffer,
137	  col: number,
138	  row: number,
139	): [number, number] {
140	  const lines = buffer.getViewportLines();
141	  const line = lines[row];
142	  if (!line) return [col, col + 1];
143	
144	  const isWord = (x: number) => {
145	    const ch = line[x]?.char;
146	    return ch != null && ch !== '' && ch !== ' ';
147	  };
148	
149	  if (!isWord(col)) return [col, col + 1];
150	
151	  let start = col;
152	  while (start > 0 && isWord(start - 1)) start--;
153	  let end = col;
154	  while (end < line.length && isWord(end)) end++;
155	  return [start, end];
156	}
157	
158	// ────────────────────────────────────────────────────────────────────────────
159	// Component
160	// ────────────────────────────────────────────────────────────────────────────
161	
162	export const SkiaTerminal = React.forwardRef<SkiaTerminalHandle, SkiaTerminalProps>(({
163	  wsUrl,
164	  webSocket: externalWs,
165	  fontSize = 14,
166	  fontConfig,
167	  scrollback = 1000,
168	  theme = DEFAULT_THEME,
169	  cursorBlinkInterval = 600,
170	  onData,
171	  onTitleChange,
172	  onBell,
173	  onConnectionChange,
174	  onSelectionChange,
175	  onResize,
176	  width: propWidth,
177	  height: propHeight,
178	  cols: propCols,
179	  rows: propRows,
180	}, ref) => {
181	  // ── Layout ──────────────────────────────────────────────────────────
182	  const [layoutSize, setLayoutSize] = useState({ width: 0, height: 0 });
183	  const [keyboardHeight, setKeyboardHeight] = useState(0);
184	
185	  const screenDims = Dimensions.get('window');
186	  const containerWidth = propWidth || layoutSize.width || screenDims.width;
187	  const containerHeight = (propHeight || layoutSize.height || screenDims.height) - keyboardHeight;
188	
189	  // Rough cell size before fonts load (will be refined)
190	  const cellWidth = fontSize * 0.6;
191	  const cellHeight = fontSize * 1.2;
192	  const cols = propCols || Math.max(1, Math.floor(containerWidth / cellWidth));
193	  const rows = propRows || Math.max(1, Math.floor(containerHeight / cellHeight));
194	
195	  // ── Keyboard avoidance ────────────────────────────────────────────
196	  useEffect(() => {
197	    const showSub = Keyboard.addListener(
198	      Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow',
199	      (e) => setKeyboardHeight(e.endCoordinates.height),
200	    );
201	    const hideSub = Keyboard.addListener(
202	      Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide',
203	      () => setKeyboardHeight(0),
204	    );
205	    return () => { showSub.remove(); hideSub.remove(); };
206	  }, []);
207	
208	  // ── Buffer ──────────────────────────────────────────────────────────
209	  const bufferRef = useRef<TerminalBuffer | null>(null);
210	  if (!bufferRef.current) {
211	    bufferRef.current = new TerminalBuffer(cols, rows, scrollback);
212	  }
213	  const buffer = bufferRef.current;
214	
215	  // Wire up terminal response callback (DA, DSR replies sent back to host)
216	  useEffect(() => {
217	    buffer.onResponse = (data: string) => {
218	      onData?.(data);
219	    };
220	    return () => { buffer.onResponse = null; };
221	  }, [buffer, onData]);
222	
223	  // ── Render trigger (rAF-based) ────────────────────────────────────
224	  const [renderVersion, setRenderVersion] = useState(0);
225	  const rafRef = useRef<number | null>(null);
226	  const pendingRender = useRef(false);
227	
228	  const scheduleRender = useCallback(() => {
229	    if (pendingRender.current) return;
230	    pendingRender.current = true;
231	    rafRef.current = requestAnimationFrame(() => {
232	      pendingRender.current = false;
233	      setRenderVersion((v) => v + 1);
234	    });
235	  }, []);
236	
237	  useEffect(() => {
238	    return () => {
239	      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
240	    };
241	  }, []);
242	
243	  // ── Connection state ──────────────────────────────────────────────
244	  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected');
245	  const [focused, setFocused] = useState(false);
246	
247	  useEffect(() => {
248	    tinfo('conn', `status → ${connectionStatus}`);
249	    onConnectionChange?.(connectionStatus);
250	  }, [connectionStatus, onConnectionChange]);
251	
252	  // ── Selection state ───────────────────────────────────────────────
253	  const [selection, setSelection] = useState<SelectionRange | null>(null);
254	  const containerRef = useRef<View>(null);
255	  const selectionRef = useRef<SelectionRange | null>(null);
256	  selectionRef.current = selection;
257	
258	  const textInputRef = useRef<TextInput>(null);
259	
260	  const copySelection = useCallback(() => {
261	    if (!selectionRef.current) return;
262	    const text = extractSelectionText(buffer, selectionRef.current);
263	    if (text) {
264	      copyToClipboard(text);
265	      onSelectionChange?.(text);
266	    }
267	    setSelection(null);
268	  }, [buffer, onSelectionChange]);
269	
270	  // ── Web mouse selection ─────────────────────────────────────────
271	  useEffect(() => {
272	    if (Platform.OS !== 'web') return;
273	    const el = (containerRef.current as unknown as HTMLElement);
274	    if (!el) return;
275	
276	    let isDragging = false;
277	    let startCol = 0;
278	    let startRow = 0;
279	    let didMove = false;
280	
281	    const toCell = (e: MouseEvent) => {
282	      const rect = el.getBoundingClientRect();
283	      return {
284	        col: Math.max(0, Math.min(buffer.cols, Math.floor((e.clientX - rect.left) / cellWidth))),
285	        row: Math.max(0, Math.min(buffer.rows - 1, Math.floor((e.clientY - rect.top) / cellHeight))),
286	      };
287	    };
288	
289	    const onMouseDown = (e: MouseEvent) => {
290	      if (e.button !== 0) return;
291	      const { col, row } = toCell(e);
292	      startCol = col;
293	      startRow = row;
294	      isDragging = true;
295	      didMove = false;
296	      setSelection(null);
297	    };
298	
299	    const onMouseMove = (e: MouseEvent) => {
300	      if (!isDragging) return;
301	      const { col, row } = toCell(e);
302	      if (!didMove && col === startCol && row === startRow) return;
303	      didMove = true;
304	      setSelection({ start: [startCol, startRow], end: [col, row] });
305	      scheduleRender();
306	    };
307	
308	    const onMouseUp = (e: MouseEvent) => {
309	      if (!isDragging) return;
310	      isDragging = false;
311	      if (!didMove) {
312	        // Click without drag — clear selection, focus input
313	        setSelection(null);
314	        textInputRef.current?.focus();
315	        return;
316	      }
317	      const { col, row } = toCell(e);
318	      const sel: SelectionRange = { start: [startCol, startRow], end: [col, row] };
319	      setSelection(sel);
320	      scheduleRender();
321	    };
322	
323	    const onDblClick = (e: MouseEvent) => {
324	      const { col, row } = toCell(e);
325	      const [wStart, wEnd] = findWordAt(buffer, col, row);
326	      setSelection({ start: [wStart, row], end: [wEnd, row] });
327	      scheduleRender();
328	    };
329	
330	    el.addEventListener('mousedown', onMouseDown);
331	    el.addEventListener('mousemove', onMouseMove);
332	    el.addEventListener('mouseup', onMouseUp);
333	    el.addEventListener('dblclick', onDblClick);
334	    return () => {
335	      el.removeEventListener('mousedown', onMouseDown);
336	      el.removeEventListener('mousemove', onMouseMove);
337	      el.removeEventListener('mouseup', onMouseUp);
338	      el.removeEventListener('dblclick', onDblClick);
339	    };
340	  }, [buffer, cellWidth, cellHeight, scheduleRender]);
341	
342	  // ── Web Ctrl/Cmd+C to copy selection ────────────────────────────
343	  useEffect(() => {
344	    if (Platform.OS !== 'web') return;
345	    const onKeyDown = (e: KeyboardEvent) => {
346	      if ((e.ctrlKey || e.metaKey) && e.key === 'c' && selectionRef.current) {
347	        e.preventDefault();
348	        copySelection();
349	      }
350	    };
351	    window.addEventListener('keydown', onKeyDown);
352	    return () => window.removeEventListener('keydown', onKeyDown);
353	  }, [copySelection]);
354	
355	  // ── WebSocket ─────────────────────────────────────────────────────
356	  const wsRef = useRef<WebSocket | null>(null);
357	
358	  const sendToServer = useCallback((data: string) => {
359	    tdebug('input', 'send', { data: hexPreview(data, 60), len: data.length });
360	    if (wsRef.current?.readyState === WebSocket.OPEN) {
361	      wsRef.current.send(data);
362	    }
363	    onData?.(data);
364	  }, [onData]);
365	
366	  useEffect(() => {
367	    const ws = externalWs || (wsUrl ? new WebSocket(wsUrl) : null);
368	    if (!ws) return;
369	
370	    wsRef.current = ws;
371	    if (ws.readyState === WebSocket.CONNECTING) {
372	      setConnectionStatus('connecting');
373	    } else if (ws.readyState === WebSocket.OPEN) {
374	      setConnectionStatus('connected');
375	    }
376	
377	    const prevOnOpen = ws.onopen;
378	    ws.onopen = (ev) => {
379	      setConnectionStatus('connected');
380	      // Send initial size
381	      try {
382	        ws.send(JSON.stringify({
383	          type: 'resize',
384	          cols: buffer.cols,
385	          rows: buffer.rows,
386	        }));
387	      } catch {}
388	      if (typeof prevOnOpen === 'function') prevOnOpen.call(ws, ev);
389	    };
390	
391	    ws.onmessage = (event) => {
392	      const data = typeof event.data === 'string' ? event.data : '';
393	      tdebug('output', 'ws.message', { data: hexPreview(data, 80), len: data.length });
394	      buffer.write(data);
395	      scheduleRender();
396	    };
397	
398	    ws.onerror = (ev) => { twarn('conn', 'ws error', { ev: String((ev as any)?.message ?? ev) }); setConnectionStatus('error'); };
399	    ws.onclose = (ev) => { tinfo('conn', 'ws close', { code: (ev as any)?.code, reason: (ev as any)?.reason }); setConnectionStatus('disconnected'); };
400	
401	    return () => {
402	      if (!externalWs && ws.readyState !== WebSocket.CLOSED) {
403	        ws.close();
404	      }
405	      wsRef.current = null;
406	    };
407	  }, [wsUrl, externalWs, buffer, scheduleRender]);
408	
409	  // ── OSC / Bell hooks on buffer ────────────────────────────────────
410	  // Override executeOsc on the buffer to capture title changes
411	  useEffect(() => {
412	    const origOsc = buffer.executeOsc.bind(buffer);
413	    buffer.executeOsc = (id: number, data: string) => {
414	      origOsc(id, data);
415	      if ((id === 0 || id === 2) && onTitleChange) {
416	        onTitleChange(data);
417	      }
418	    };
419	
420	    const origC0 = buffer.executeC0.bind(buffer);
421	    buffer.executeC0 = (code: number) => {
422	      origC0(code);
423	      if (code === 0x07 && onBell) {
424	        onBell();
425	        Vibration.vibrate(50);
426	      }
427	    };
428	  }, [buffer, onTitleChange, onBell]);
429	
430	  // ── Keyboard input ────────────────────────────────────────────────
431	  const lastInputRef = useRef('');
432	
433	  // Track modifier keys (best-effort on RN)
434	  const modifiersRef = useRef({ ctrl: false, meta: false, alt: false, shift: false });
435	
436	  const handleKeyPress = useCallback((
437	    e: NativeSyntheticEvent<TextInputKeyPressEventData>,
438	  ) => {
439	    const { key } = e.nativeEvent;
440	
441	    // Special keys → escape sequences
442	    const keyMap: Record<string, string> = {
443	      'Enter': '\r',
444	      'Backspace': '\x7f',
445	      'Escape': '\x1b',
446	      'Tab': '\t',
447	      'ArrowUp': '\x1b[A',
448	      'ArrowDown': '\x1b[B',
449	      'ArrowRight': '\x1b[C',
450	      'ArrowLeft': '\x1b[D',
451	      'Home': '\x1b[H',
452	      'End': '\x1b[F',
453	      'PageUp': '\x1b[5~',
454	      'PageDown': '\x1b[6~',
455	      'Delete': '\x1b[3~',
456	      'Insert': '\x1b[2~',
457	      'F1': '\x1bOP', 'F2': '\x1bOQ', 'F3': '\x1bOR', 'F4': '\x1bOS',
458	      'F5': '\x1b[15~', 'F6': '\x1b[17~', 'F7': '\x1b[18~', 'F8': '\x1b[19~',
459	      'F9': '\x1b[20~', 'F10': '\x1b[21~', 'F11': '\x1b[23~', 'F12': '\x1b[24~',
460	    };
461	
462	    if (keyMap[key]) {
463	      // Clear selection on any non-copy keystroke
464	      if (selectionRef.current) {
465	        setSelection(null);
466	        onSelectionChange?.(null);
467	      }
468	      sendToServer(keyMap[key]);
469	      lastInputRef.current = key;
470	    } else if (key.length === 1) {
471	      const code = key.charCodeAt(0);
472	      // Ctrl+C (0x03) with active selection → copy instead of sending to terminal
473	      if (code === 3 && selectionRef.current) {
474	        copySelection();
475	        lastInputRef.current = key;
476	        return;
477	      }
478	      // Clear selection on any other keystroke
479	      if (selectionRef.current) {
480	        setSelection(null);
481	        onSelectionChange?.(null);
482	      }
483	      sendToServer(key);
484	      lastInputRef.current = key;
485	    }
486	  }, [sendToServer, selection, onSelectionChange]);
487	
488	  const handleTextChange = useCallback((text: string) => {
489	    // onChangeText fires for regular character input and IME
490	    // Avoid double-sending if onKeyPress already handled it
491	    if (text.length > 0 && text !== lastInputRef.current) {
492	      sendToServer(text);
493	    }
494	    lastInputRef.current = '';
495	    setTimeout(() => textInputRef.current?.clear(), 0);
496	  }, [sendToServer]);
497	
498	  // ── Gestures ──────────────────────────────────────────────────────
499	
500	  const clearSelection = useCallback(() => {
501	    if (!selectionRef.current) return;
502	    setSelection(null);
503	    onSelectionChange?.(null);
504	  }, [onSelectionChange]);
505	
506	  const handleTapGestureEnd = useCallback(() => {
507	    textInputRef.current?.focus();
508	    clearSelection();
509	  }, [clearSelection]);
510	
511	  const scrollRemainderRef = useRef(0);
512	  const lastPanTranslationRef = useRef(0);
513	  const handleScrollGestureUpdate = useCallback((translationY: number) => {
514	    const deltaY = translationY - lastPanTranslationRef.current;
515	    lastPanTranslationRef.current = translationY;
516	    scrollRemainderRef.current += deltaY;
517	
518	    const linesToScroll = Math.trunc(scrollRemainderRef.current / cellHeight);
519	    if (linesToScroll === 0) return;
520	
521	    scrollRemainderRef.current -= linesToScroll * cellHeight;
522	    const maxScroll = buffer.ybase;
523	    const newDisp = Math.max(-maxScroll, Math.min(0, buffer.ydisp + linesToScroll));
524	    if (newDisp !== buffer.ydisp) {
525	      buffer.ydisp = newDisp;
526	      scheduleRender();
527	    }
528	  }, [buffer, cellHeight, scheduleRender]);
529	
530	  const handleScrollGestureEnd = useCallback(() => {
531	    scrollRemainderRef.current = 0;
532	    lastPanTranslationRef.current = 0;
533	  }, []);
534	
535	  const handleLongPressGestureStart = useCallback((x: number, y: number) => {
536	    const col = Math.floor(x / cellWidth);
537	    const row = Math.floor(y / cellHeight);
538	    if (col >= 0 && col < buffer.cols && row >= 0 && row < buffer.rows) {
539	      const [wStart, wEnd] = findWordAt(buffer, col, row);
540	      setSelection({ start: [wStart, row], end: [wEnd, row] });
541	      if (Platform.OS !== 'web') Vibration.vibrate(30);
542	    }
543	  }, [buffer, cellWidth, cellHeight]);
544	
545	  const handleSelectionPanUpdate = useCallback((x: number, y: number) => {
546	    if (!selectionRef.current) return;
547	    const col = Math.max(0, Math.min(buffer.cols, Math.floor(x / cellWidth)));
548	    const row = Math.max(0, Math.min(buffer.rows - 1, Math.floor(y / cellHeight)));
549	    setSelection((prev) => prev ? { ...prev, end: [col, row] } : null);
550	  }, [buffer, cellWidth, cellHeight]);
551	
552	  const handleSelectionPanEnd = useCallback(() => {
553	    if (selectionRef.current) {
554	      onSelectionChange?.(extractSelectionText(buffer, selectionRef.current));
555	    }
556	  }, [buffer, onSelectionChange]);
557	
558	  // Tap → focus
559	  const tapGesture = Gesture.Tap()
560	    .onEnd(() => {
561	      'worklet';
562	      runOnJS(handleTapGestureEnd)();
563	    });
564	
565	  // Pan → scroll through scrollback
566	  const panGesture = Gesture.Pan()
567	    .onUpdate((e) => {
568	      'worklet';
569	      runOnJS(handleScrollGestureUpdate)(e.translationY);
570	    })
571	    .onEnd(() => {
572	      'worklet';
573	      runOnJS(handleScrollGestureEnd)();
574	    });
575	
576	  // Long press → select word at position
577	  const longPressGesture = Gesture.LongPress()
578	    .minDuration(400)
579	    .onStart((e) => {
580	      'worklet';
581	      runOnJS(handleLongPressGestureStart)(e.x, e.y);
582	    });
583	
584	  // Pan after long press → extend selection
585	  const selectionPanGesture = Gesture.Pan()
586	    .activateAfterLongPress(400)
587	    .onUpdate((e) => {
588	      'worklet';
589	      runOnJS(handleSelectionPanUpdate)(e.x, e.y);
590	    })
591	    .onEnd(() => {
592	      'worklet';
593	      runOnJS(handleSelectionPanEnd)();
594	    });
595	
596	  const composedGestures = Gesture.Race(
597	    selectionPanGesture,
598	    Gesture.Exclusive(longPressGesture, tapGesture),
599	    panGesture,
600	  );
601	
602	  // ── Resize ────────────────────────────────────────────────────────
603	  useEffect(() => {
604	    const newCols = propCols || Math.max(1, Math.floor(containerWidth / cellWidth));
605	    const newRows = propRows || Math.max(1, Math.floor(containerHeight / cellHeight));
606	
607	    if (newCols !== buffer.cols || newRows !== buffer.rows) {
608	      tinfo('resize', `${buffer.cols}x${buffer.rows} → ${newCols}x${newRows}`, {
609	        containerWidth, containerHeight, cellWidth, cellHeight,
610	      });
611	      buffer.resize(newCols, newRows);
612	      scheduleRender();
613	      onResize?.(newCols, newRows);
614	
615	      if (wsRef.current?.readyState === WebSocket.OPEN) {
616	        try {
617	          wsRef.current.send(JSON.stringify({
618	            type: 'resize', cols: newCols, rows: newRows,
619	          }));
620	        } catch {}
621	      }
622	    }
623	  }, [containerWidth, containerHeight, cellWidth, cellHeight, propCols, propRows, buffer, scheduleRender, onResize]);
624	
625	  // ── Layout callback ───────────────────────────────────────────────
626	  const onLayout = useCallback((e: LayoutChangeEvent) => {
627	    const { width: w, height: h } = e.nativeEvent.layout;
628	    setLayoutSize({ width: w, height: h });
629	  }, []);
630	
631	  // ── Imperative handle ─────────────────────────────────────────────
632	  React.useImperativeHandle(ref, () => ({
633	    write: (data: string) => {
634	      tdebug('output', 'write', { data: hexPreview(data, 80), len: data.length });
635	      buffer.write(data);
636	      scheduleRender();
637	    },
638	    focus: () => textInputRef.current?.focus(),
639	    blur: () => textInputRef.current?.blur(),
640	    getSelection: () => selection ? extractSelectionText(buffer, selection) : null,
641	    clearSelection: () => { setSelection(null); onSelectionChange?.(null); },
642	    scrollToBottom: () => {
643	      buffer.ydisp = 0;
644	      scheduleRender();
645	    },
646	    buffer,
647	  }), [buffer, selection, scheduleRender, onSelectionChange]);
648	
649	  // ── Render ────────────────────────────────────────────────────────
650	
651	  const termWidth = Math.max(1, containerWidth);
652	  const termHeight = Math.max(1, containerHeight);
653	
654	  const handleTerminalPress = useCallback(() => {
655	    textInputRef.current?.focus();
656	    if (selection) {
657	      setSelection(null);
658	      onSelectionChange?.(null);
659	    }
660	  }, [selection, onSelectionChange]);
661	
662	  return (
663	    <GestureHandlerRootView style={[styles.container, { width: propWidth, height: propHeight }]}>
664	      <View ref={containerRef} style={styles.fill} onLayout={onLayout}>
665	        <GestureDetector gesture={composedGestures}>
666	          <Pressable style={styles.fill} onPress={handleTerminalPress}>
667	            <SkiaTerminalRenderer
668	              buffer={buffer}
669	              fontSize={fontSize}
670	              fontConfig={fontConfig}
671	              theme={theme}
672	              width={termWidth}
673	              height={termHeight}
674	              renderVersion={renderVersion}
675	              selection={selection}
676	              focused={focused}
677	              cursorBlinkInterval={cursorBlinkInterval}
678	            />
679	          </Pressable>
680	        </GestureDetector>
681	
682	        {/* Native context menu */}
683	        {Platform.OS !== 'web' && selection && (
684	          <View
685	            style={[
686	              styles.contextMenu,
687	              {
688	                left: Math.max(8, ((Math.min(selection.start[0], selection.end[0]) +
689	                  Math.max(selection.start[0], selection.end[0])) / 2) * cellWidth - 30),
690	                top: Math.max(4, Math.min(selection.start[1], selection.end[1]) * cellHeight - 38),
691	              },
692	            ]}
693	          >
694	            <Pressable
695	              style={({ pressed }) => [styles.contextMenuItem, pressed && { opacity: 0.6 }]}
696	              onPress={copySelection}
697	            >
698	              <Text style={styles.contextMenuText}>Copy</Text>
699	            </Pressable>
700	          </View>
701	        )}
702	
703	        <TextInput
704	          ref={textInputRef}
705	          style={styles.hiddenInput}
706	          autoCapitalize="none"
707	          autoCorrect={false}
708	          autoComplete="off"
709	          spellCheck={false}
710	          keyboardType="ascii-capable"
711	          keyboardAppearance="dark"
712	          onKeyPress={handleKeyPress}
713	          onChangeText={handleTextChange}
714	          onFocus={() => setFocused(true)}
715	          onBlur={() => setFocused(false)}
716	          blurOnSubmit={false}
717	          caretHidden
718	          textContentType="none"
719	          importantForAutofill="no"
720	          // Prevent password autofill prompts on iOS
721	          secureTextEntry={false}
722	        />
723	      </View>
724	    </GestureHandlerRootView>
725	  );
726	});
727	
728	SkiaTerminal.displayName = 'SkiaTerminal';
729	
730	const styles = StyleSheet.create({
731	  container: {
732	    flex: 1,
733	  },
734	  fill: {
735	    flex: 1,
736	  },
737	  hiddenInput: {
738	    position: 'absolute',
739	    opacity: 0,
740	    width: 1,
741	    height: 1,
742	    left: -9999,
743	    top: -9999,
744	  },
745	  contextMenu: {
746	    position: 'absolute',
747	    backgroundColor: '#2a2a2a',
748	    borderRadius: 8,
749	    paddingHorizontal: 2,
750	    paddingVertical: 2,
751	    flexDirection: 'row',
752	    shadowColor: '#000',
753	    shadowOffset: { width: 0, height: 2 },
754	    shadowOpacity: 0.4,
755	    shadowRadius: 6,
756	    elevation: 8,
757	    zIndex: 100,
758	  },
759	  contextMenuItem: {
760	    paddingHorizontal: 14,
761	    paddingVertical: 6,
762	    borderRadius: 6,
763	  },
764	  contextMenuText: {
765	    color: '#ffffff',
766	    fontSize: 13,
767	    fontWeight: '500',
768	  },
769	});
770	
771	// ────────────────────────────────────────────────────────────────────────────
772	// Hook: standalone terminal (no WebSocket)
773	// ────────────────────────────────────────────────────────────────────────────
774	
775	export function useTerminal(cols = 80, rows = 24, scrollback = 1000) {
776	  const bufferRef = useRef(new TerminalBuffer(cols, rows, scrollback));
777	  const [version, setVersion] = useState(0);
778	
779	  const write = useCallback((data: string) => {
780	    bufferRef.current.write(data);
781	    setVersion((v) => v + 1);
782	  }, []);
783	
784	  const reset = useCallback(() => {
785	    bufferRef.current.write('\x1bc'); // RIS
786	    setVersion((v) => v + 1);
787	  }, []);
788	
789	  return {
790	    buffer: bufferRef.current,
791	    write,
792	    reset,
793	    renderVersion: version,
794	  };
795	}
