430	export function expandCompactRow(compact: Uint32Array, cols: number): Uint32Array {
431	  const full = new Uint32Array(cols * CELL_SIZE);
432	  const srcCols = compact.length >>> 1; // compact.length / 2
433	  const copyCols = Math.min(srcCols, cols);
434	  for (let c = 0; c < copyCols; c++) {
435	    full[c * CELL_SIZE] = compact[c * 2];
436	    full[c * CELL_SIZE + 1] = compact[c * 2 + 1];
437	    // words 2,3 default to 0 (no RGB)
438	  }
439	  for (let c = copyCols; c < cols; c++) {
440	    full[c * CELL_SIZE] = DEFAULT_CELL_W0;
441	    full[c * CELL_SIZE + 1] = DEFAULT_CELL_W1;
442	  }
443	  return full;
444	}
445	
446	// ---------------------------------------------------------------------------
447	// Selection text extraction
448	// ---------------------------------------------------------------------------
449	
450	export interface SelectionRange {
451	  startRow: number;
452	  startCol: number;
453	  endRow: number;
454	  endCol: number;
455	}
456	
457	/**
458	 * Normalize a selection so that start is before end.
459	 */
460	export function normalizeSelection(sel: SelectionRange): SelectionRange {
461	  let { startRow, startCol, endRow, endCol } = sel;
462	  if (startRow > endRow || (startRow === endRow && startCol > endCol)) {
463	    const tmpR = startRow;
464	    const tmpC = startCol;
465	    startRow = endRow;
466	    startCol = endCol;
467	    endRow = tmpR;
468	    endCol = tmpC;
469	  }
470	  return { startRow, startCol, endRow, endCol };
471	}
472	
473	/**
474	 * Extract text from a CellGrid for the given selection range.
475	 *
476	 * - Normalizes the selection (handles backwards selections).
477	 * - Trims trailing spaces from each line.
478	 * - Joins lines with `\n`.
479	 */
480	export function extractText(
481	  grid: CellGrid,
482	  startRow: number,
483	  startCol: number,
484	  endRow: number,
485	  endCol: number,
486	): string {
487	  const sel = normalizeSelection({ startRow, startCol, endRow, endCol });
488	  const sr = Math.max(0, sel.startRow);
489	  const er = Math.min(grid.rows - 1, sel.endRow);
490	  const lines: string[] = [];
491	
492	  for (let row = sr; row <= er; row++) {
493	    let colStart = 0;
494	    let colEnd = grid.cols - 1;
495	
496	    if (row === sr) colStart = Math.max(0, sel.startCol);
497	    if (row === er) colEnd = Math.min(grid.cols - 1, sel.endCol);
498	
499	    // Snap selection start to the leading cell of a wide character so
500	    // clicking on the right half still includes the full character (#6).
501	    if (colStart > 0 && grid.isSpacerCell(row, colStart)) {
502	      colStart--;
503	    }
504	
505	    let line = "";
506	    for (let col = colStart; col <= colEnd; col++) {
507	      // Skip spacer cells (right half of wide characters)
508	      if (grid.isSpacerCell(row, col)) continue;
509	      const cp = grid.getCodepoint(row, col);
510	      line += cp > 0x20 ? String.fromCodePoint(cp) : " ";
511	    }
512	
513	    // Trim trailing spaces
514	    line = line.replace(/\s+$/, "");
515	
516	    // If previous row wraps into this one, append without newline
517	    if (row > sr && grid.isWrapped(row - 1)) {
518	      lines[lines.length - 1] += line;
519	    } else {
520	      lines.push(line);
521	    }
522	  }
523	
524	  return lines.join("\n");
525	}
