1	import { CELL_SIZE, CellGrid } from "./cell-grid";
2	import type { CursorState } from "./types";
3	
4	export class Buffer {
5	  readonly grid: CellGrid;
6	  cursor: CursorState;
7	  scrollTop: number;
8	  scrollBottom: number;
9	  /** Default tab-stop interval. */
10	  private readonly tabWidth = 8;
11	  /** Custom tab stops (column indices). */
12	  tabStops: Set<number>;
13	
14	  // Saved cursor for DECSC / DECRC
15	  private savedCursor: CursorState | null = null;
16	
17	  constructor(
18	    public readonly cols: number,
19	    public readonly rows: number,
20	    existingGrid?: CellGrid,
21	  ) {
22	    this.grid = existingGrid ?? new CellGrid(cols, rows);
23	    this.cursor = { row: 0, col: 0, visible: true, style: "block", wrapPending: false };
24	    this.scrollTop = 0;
25	    this.scrollBottom = rows - 1;
26	    this.tabStops = new Set<number>();
27	    this.resetTabStops();
28	  }
29	
30	  private resetTabStops(): void {
31	    this.tabStops.clear();
32	    for (let c = this.tabWidth; c < this.cols; c += this.tabWidth) {
33	      this.tabStops.add(c);
34	    }
35	  }
36	
37	  nextTabStop(col: number): number {
38	    for (let c = col + 1; c < this.cols; c++) {
39	      if (this.tabStops.has(c)) return c;
40	    }
41	    return this.cols - 1;
42	  }
43	
44	  prevTabStop(col: number): number {
45	    for (let c = col - 1; c >= 0; c--) {
46	      if (this.tabStops.has(c)) return c;
47	    }
48	    return 0;
49	  }
50	
51	  saveCursor(): void {
52	    this.savedCursor = { ...this.cursor };
53	  }
54	
55	  restoreCursor(): void {
56	    if (this.savedCursor) {
57	      this.cursor = { ...this.savedCursor };
58	    }
59	  }
60	
61	  /** Scroll the scroll region up by one line. */
62	  scrollUp(): void {
63	    if (this.scrollTop === 0 && this.scrollBottom === this.rows - 1) {
64	      // Full-screen scroll: O(1) rotation instead of O(rows×cols) copy
65	      this.grid.rotateUp();
66	      this.grid.clearRowRaw(this.scrollBottom);
67	      this.grid.markDirtyRange(this.scrollTop, this.scrollBottom);
68	    } else {
69	      // Partial scroll region: shift rows up using copyWithin on physical offsets
70	      const rowSize = this.cols * CELL_SIZE;
71	      for (let r = this.scrollTop; r < this.scrollBottom; r++) {
72	        const dst = this.grid.rowStart(r);
73	        const src = this.grid.rowStart(r + 1);
74	        this.grid.data.copyWithin(dst, src, src + rowSize);
75	        this.grid.setWrapped(r, this.grid.isWrapped(r + 1));
76	      }
77	      this.grid.clearRowRaw(this.scrollBottom);
78	      this.grid.markDirtyRange(this.scrollTop, this.scrollBottom);
79	    }
80	  }
81	
82	  /**
83	   * Scroll the scroll region down by one line.
84	   */
85	  scrollDown(): void {
86	    if (this.scrollTop === 0 && this.scrollBottom === this.rows - 1) {
87	      // Full-screen scroll: O(1) rotation
88	      this.grid.rotateDown();
89	      this.grid.clearRowRaw(this.scrollTop);
90	      this.grid.markDirtyRange(this.scrollTop, this.scrollBottom);
91	    } else {
92	      // Partial scroll region: shift rows down using copyWithin on physical offsets
93	      const rowSize = this.cols * CELL_SIZE;
94	      for (let r = this.scrollBottom; r > this.scrollTop; r--) {
95	        const dst = this.grid.rowStart(r);
96	        const src = this.grid.rowStart(r - 1);
97	        this.grid.data.copyWithin(dst, src, src + rowSize);
98	        this.grid.setWrapped(r, this.grid.isWrapped(r - 1));
99	      }
100	      this.grid.clearRowRaw(this.scrollTop);
101	      this.grid.markDirtyRange(this.scrollTop, this.scrollBottom);
102	    }
103	  }
104	}
105	
106	export class BufferSet {
107	  normal: Buffer;
108	  alternate: Buffer;
109	  active: Buffer;
110	
111	  /** Scrollback lines for the normal buffer (array of Uint32Array). */
112	  scrollback: Uint32Array[];
113	  /** Per-line wrap flag for scrollback (parallel to scrollback[]). */
114	  scrollbackWrap: boolean[];
115	  /** True if the corresponding scrollback row uses compact (2 word/cell) format. */
116	  scrollbackCompact: boolean[];
117	  readonly maxScrollback: number;
118	
119	  constructor(
120	    public readonly cols: number,
121	    public readonly rows: number,
122	    maxScrollback = 5000,
123	    sharedBuffer?: SharedArrayBuffer,
124	    sharedAltBuffer?: SharedArrayBuffer,
125	  ) {
126	    this.normal = sharedBuffer
127	      ? new Buffer(cols, rows, new CellGrid(cols, rows, sharedBuffer))
128	      : new Buffer(cols, rows);
129	    this.alternate = sharedAltBuffer
130	      ? new Buffer(cols, rows, new CellGrid(cols, rows, sharedAltBuffer))
131	      : new Buffer(cols, rows);
132	    this.active = this.normal;
133	    this.scrollback = [];
134	    this.scrollbackWrap = [];
135	    this.scrollbackCompact = [];
136	    this.maxScrollback = maxScrollback;
137	  }
138	
139	  get isAlternate(): boolean {
140	    return this.active === this.alternate;
141	  }
142	
143	  activateAlternate(): void {
144	    if (this.active === this.alternate) return;
145	    this.active = this.alternate;
146	    this.alternate.grid.clear();
147	    this.alternate.cursor = { row: 0, col: 0, visible: true, style: "block", wrapPending: false };
148	    this.alternate.scrollTop = 0;
149	    this.alternate.scrollBottom = this.rows - 1;
150	  }
151	
152	  activateNormal(): void {
153	    if (this.active === this.normal) return;
154	    this.active = this.normal;
155	  }
156	
157	  /**
158	   * Switch the active buffer pointer without side effects.
159	   *
160	   * Unlike activateAlternate() which clears the grid and resets the
161	   * cursor, this only sets the active reference. Used in worker mode
162	   * where the worker has already prepared the buffer content.
163	   */
164	  setActive(isAlternate: boolean): void {
165	    this.active = isAlternate ? this.alternate : this.normal;
166	  }
167	
168	  /**
169	   * Push a line into scrollback (for the normal buffer).
170	   *
171	   * IMPORTANT: push() must happen before shift() — borrowRowBuffer()
172	   * returns scrollback[0] which the caller fills before calling this.
173	   * Reversing the order would evict the buffer before it's appended.
174	   */
175	  pushScrollback(line: Uint32Array, wrapped = false, compact = false): void {
176	    this.scrollback.push(line);
177	    this.scrollbackWrap.push(wrapped);
178	    this.scrollbackCompact.push(compact);
179	    if (this.scrollback.length > this.maxScrollback) {
180	      this.scrollback.shift();
181	      this.scrollbackWrap.shift();
182	      this.scrollbackCompact.shift();
183	    }
184	  }
185	
186	  /**
187	   * Get a reusable row buffer or allocate a new one.
188	   * Reuses the buffer that's about to be evicted from scrollback.
189	   */
190	  borrowRowBuffer(size: number): Uint32Array {
191	    if (this.scrollback.length >= this.maxScrollback && this.maxScrollback > 0) {
192	      const existing = this.scrollback[0];
193	      if (existing && existing.length === size) {
194	        return existing;
195	      }
196	    }
197	    return new Uint32Array(size);
198	  }
199	
200	  /** Scroll the active buffer up, pushing the top line into scrollback if normal buffer. */
201	  scrollUpWithHistory(): void {
202	    if (this.maxScrollback > 0 && this.active === this.normal && this.active.scrollTop === 0) {
203	      const grid = this.active.grid;
204	      const hasRgb = grid.rowHasRgb(0);
205	      const rowSize = hasRgb ? grid.cols * CELL_SIZE : grid.cols * 2;
206	      const dest = this.borrowRowBuffer(rowSize);
207	      if (hasRgb) {
208	        grid.copyRowInto(0, dest);
209	      } else {
210	        // Compact: copy only words 0,1 per cell
211	        const start = grid.rowStart(0);
212	        for (let c = 0; c < grid.cols; c++) {
213	          dest[c * 2] = grid.data[start + c * CELL_SIZE];
214	          dest[c * 2 + 1] = grid.data[start + c * CELL_SIZE + 1];
215	        }
